const SYSTEME = "Tu rédiges des e-mails pour CountMeIn, une plateforme marocaine qui met en relation bénévoles et associations. Écris en français, tutoie le bénévole, avec un ton chaleureux, simple et concret. Utilise uniquement les informations fournies dans les données : n'invente ni date, ni horaire, ni lieu, ni consigne, ni matériel, ni chiffre. Si une information manque, n'en parle pas. Pas de formule de politesse finale ni de signature (elles sont ajoutées par le gabarit). Au plus un émoji dans tout l'e-mail. Le sujet fait moins de 70 caractères. Tâche : présenter au bénévole les missions recommandées pour lui cette semaine. Écris une introduction courte, puis pour chaque mission une phrase qui explique pourquoi elle lui correspond, en t'appuyant uniquement sur les champs fournis (distance, domaine qui l'intéresse, participation passée avec cette association ou ce domaine, pourcentage de places encore libres). Ne cite jamais le score chiffré. Reprends exactement les identifiants de mission fournis.";
const SCHEMA = {"type": "object", "properties": {"sujet": {"type": "string"}, "titre": {"type": "string"}, "introduction": {"type": "string"}, "explications": {"type": "array", "items": {"type": "object", "properties": {"missionId": {"type": "integer"}, "phrase": {"type": "string"}}, "required": ["missionId", "phrase"], "additionalProperties": false}}}, "required": ["sujet", "titre", "introduction", "explications"], "additionalProperties": false};
function requeteIA(donnees) {
  return {
    model: 'claude-opus-5-5',
    max_tokens: 16000,
    // Si le modèle refuse la demande, l'API la relance automatiquement sur un autre modèle
    fallbacks: 'default',
    // E-mail court : effort faible ; sortie JSON imposée par le schéma
    output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
    system: SYSTEME,
    messages: [{ role: 'user', content: 'Données :\n' + JSON.stringify(donnees, null, 2) }],
  };
}

// Un e-mail par bénévole ayant au moins une mission recommandée
return $input.all()
  .filter(item => item.json.benevoleId && (item.json.missions || []).length)
  .map(item => {
    const d = item.json;
    return { json: { ...d, requeteIA: requeteIA({
      prenom: d.prenom, ville: d.ville, centresInteret: d.centresInteret,
      missions: d.missions.map(r => ({
        missionId: r.mission.id, titre: r.mission.titre, association: r.mission.association,
        domaine: r.mission.domaine, debut: r.mission.dateDebut, ville: r.mission.ville,
        distanceKm: r.distanceKm, domaineQuiInteresse: r.domaineCorrespond,
        dejaParticipeAssociationOuDomaine: r.dejaParticipeAssociationOuDomaine,
        pourcentagePlacesLibres: r.pourcentagePlacesLibres,
      })),
    }) } };
  });

// Gabarit HTML CountMeIn (même charte que les e-mails envoyés par le backend)
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function gabarit({ badge, couleur, couleurTexte, prenom, titre, paragraphes, details, blocs, bouton, lien }) {
  const corps = (paragraphes || []).map(p =>
    `<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#444;">${esc(p)}</p>`).join('');
  const lignes = Object.entries(details || {}).filter(([, v]) => v).map(([k, v]) =>
    `<tr><td style="padding:7px 0;font-size:13px;color:#777;width:110px;vertical-align:top;">${esc(k)}</td>` +
    `<td style="padding:7px 0;font-size:14px;font-weight:700;color:#1a1a1a;">${esc(v)}</td></tr>`).join('');
  const encadre = lignes ? `<table cellpadding="0" cellspacing="0" style="width:100%;margin-top:8px;border:2px solid #1a1a1a;border-left:8px solid ${couleur};border-radius:10px;"><tr><td style="padding:12px 18px;"><table cellpadding="0" cellspacing="0" style="width:100%;">${lignes}</table></td></tr></table>` : '';
  const btn = lien ? `<table cellpadding="0" cellspacing="0" style="margin:24px 0 8px;"><tr><td style="background:${couleur};border:2px solid #1a1a1a;border-radius:10px;box-shadow:3px 3px 0 #1a1a1a;"><a href="${esc(lien)}" style="display:inline-block;padding:13px 26px;font-size:15px;font-weight:800;color:${couleurTexte};text-decoration:none;">${esc(bouton)} →</a></td></tr></table>` : '';
  return `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f5f0e8;font-family:'Helvetica Neue',Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f0e8;padding:40px 20px;"><tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#fff;border:3px solid #1a1a1a;border-radius:16px;overflow:hidden;box-shadow:6px 6px 0 #1a1a1a;">
<tr><td style="background:#f7c948;border-bottom:3px solid #1a1a1a;padding:22px 40px;">
<h1 style="margin:0;font-size:26px;font-weight:900;color:#1a1a1a;">CountMeIn</h1>
<p style="margin:4px 0 0;font-size:13px;font-weight:600;color:#1a1a1a;opacity:0.7;">Connecter · Soutenir · Agir</p></td></tr>
<tr><td style="padding:34px 40px 30px;">
<span style="display:inline-block;padding:5px 12px;background:${couleur};color:${couleurTexte};border:2px solid #1a1a1a;border-radius:999px;font-size:12px;font-weight:800;text-transform:uppercase;">${esc(badge)}</span>
<p style="margin:20px 0 6px;font-size:14px;color:#777;">Bonjour ${esc(prenom)},</p>
<h2 style="margin:0 0 14px;font-size:23px;font-weight:900;color:#1a1a1a;line-height:1.25;">${esc(titre)}</h2>
${corps}${encadre}${blocs || ''}${btn}
</td></tr>
<tr><td style="background:#1a1a1a;padding:18px 40px;"><p style="margin:0;font-size:12px;color:#aaa;text-align:center;line-height:1.6;">
© ${new Date().getFullYear()} CountMeIn — Plateforme de bénévolat au Maroc<br>Vous pouvez désactiver ces e-mails depuis la page Notifications de votre espace.</p></td></tr>
</table></td></tr></table></body></html>`;
}

// Lit la réponse de Claude : JSON conforme au schéma, sinon null (→ texte de secours, F48)
function lireReponseIA(reponse) {
  if (!reponse || !reponse.stop_reason || reponse.stop_reason === 'refusal') return null;
  const bloc = (reponse.content || []).find(b => b.type === 'text');
  if (!bloc) return null;
  try { return JSON.parse(bloc.text); } catch (e) { return null; }
}

const sources = $('Preparer la requete IA').all();
return $input.all().map((item, i) => {
  const d = sources[i].json;
  const ia = lireReponseIA(item.json) || {
    sujet: 'Tes missions recommandées cette semaine',
    titre: 'Des missions faites pour toi',
    introduction: 'Voici quelques missions proches de chez toi et dans tes domaines préférés.',
    explications: [],
  };
  const phrase = id => (ia.explications.find(e => e.missionId === id) || {}).phrase || '';
  const cartes = d.missions.map(r => {
    const m = r.mission;
    return `<table cellpadding="0" cellspacing="0" style="width:100%;margin-top:14px;border:2px solid #1a1a1a;border-radius:12px;box-shadow:3px 3px 0 #1a1a1a;">
<tr><td style="padding:14px 18px;">
<p style="margin:0;font-size:16px;font-weight:900;color:#1a1a1a;">${esc(m.titre)}</p>
<p style="margin:4px 0 0;font-size:13px;color:#777;">${esc(m.association)} · ${esc(m.ville || '')} · ${esc(m.dateDebut)}</p>
${phrase(m.id) ? `<p style="margin:10px 0 0;font-size:14px;line-height:1.6;color:#444;">${esc(phrase(m.id))}</p>` : ''}
<p style="margin:12px 0 0;"><a href="${esc(m.lien)}" style="font-size:14px;font-weight:800;color:#00864A;">Voir la mission →</a></p>
</td></tr></table>`;
  }).join('');
  return { json: {
    email: d.email,
    sujet: ia.sujet,
    html: gabarit({
      badge: 'Pour toi cette semaine', couleur: '#00864A', couleurTexte: '#ffffff', prenom: d.prenom,
      titre: ia.titre, paragraphes: [ia.introduction], blocs: cartes,
    }),
  } };
});
